{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Negotiate the general cap against the actual risk allocation, financial diligence and any warranty insurance—not in isolation."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Reduce the de minimis and basket; seek a tipping basket"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a longer general warranty period, allowing meaningful post-completion financial and operational review."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Separate capacity, authority, ownership and unencumbered-title warranties, with at least purchase-price-level protection and materially longer survival."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "fraud and deliberate concealment, with carefully agreed attribution wording."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket disclosure of public registers and materials merely referred to elsewhere."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete constructive/discoverable knowledge exclusions."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make effective consent and satisfaction of associated conditions a completion condition, waivable only by Buyer."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require payoff figures, accrued interest and fees, lender payment instructions and binding release arrangements as part of completion."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Allocate seller/transaction-related amounts expressly through an appropriate deduction, debt-like item or seller-funded payment/reserve."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Retain a broader, appropriately scoped indemnity for residual ownership and use risks, outside general warranty limitations."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a specific indemnity for the pre-completion incident, with lawful scope and negotiated duration/security."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Allocate genuinely future operating costs appropriately; deduct or otherwise address pre-completion liabilities and unauthorised commitments without double counting."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "expressly identify which limitations apply to which claims."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Require valid transfer and registration deliverables, necessary waivers/releases and robust title warranties."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "A separate tax covenant/indemnity for pre-completion tax exposures, with appropriate assessment-period survival and its own limitations."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

